# Edition 07: operational placement, small authority updates and bulk work scale independently.
iso_lab='https://sovereign-data-monitor.paulcull.chatgpt.site/isolation.html'
iso_prompt='''Operational isolation decision: use three regional work classes: authority guard, operational delivery and bulk reconciliation. Separate relay paths, queues/topics, worker groups, connection/concurrency budgets and retry/quarantine paths. A policy transaction advances scoped authority and creates a guard intent plus one reconciliation cursor; it must not enumerate affected rows. Operational commits remain local ACID with outbox/audit/idempotency. Operational priority never bypasses current policy. Source restriction commit, remote enforcement and physical convergence are separate milestones. Read the Work isolation page before implementing any queue or policy change. The interactive lab and admission specification are synthetic; the v3 database harness still has its original process lock and serial worker.\n\n'''
iso_diagram='''<div class="diagram-scroll"><svg viewBox="0 0 880 410" role="img" aria-label="Business commits feed the reserved operational lane. Policy commits feed a small authority guard lane and a separately limited reconciliation lane. All recipient writes and reads enforce the current authority."><title>Three independently budgeted work classes</title><defs><marker id="iso-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="#547760"/></marker></defs><g stroke="#547760" fill="none" marker-end="url(#iso-arrow)"><path d="M225 75 H325"/><path d="M225 240 H275 V190 H325"/><path d="M275 240 V305 H325"/><path d="M565 75 H650 V190 H680"/><path d="M565 190 H680"/><path d="M565 305 H650 V210 H680"/><path d="M765 245 V295"/></g>'''+''.join(svg_box(*b) for b in [(20,40,205,70,'Business commit','Bounded ACID + outbox'),(20,205,205,70,'Policy commit','Scoped epoch + two intents'),(325,40,240,70,'Operational lane','Reserved capacity · fresh deltas'),(325,155,240,70,'Authority guard lane','Small fences · reserved capacity'),(325,270,240,70,'Reconciliation lane','Cursors · capped bulk work'),(680,155,185,90,'Recipient gates','Current facts + atomic fence'),(680,295,185,70,'Regional store','Budgeted reads and writes')])+'''<text x="325" y="389" font-size="11" fill="#60755e">No cross-lane ordering assumption. Guard state controls visibility; purge may follow later.</text></svg></div>'''
add('work-isolation','Operational work keeps its own capacity.','Technical design / Work isolation · edition 07','Decouple the cost of changing placement from the small act of changing authority. Policy campaigns cannot sit ahead of operational records.',
call('Decision and implementation status','Adopt three independently budgeted lanes. The <a href="'+iso_lab+'">interactive isolation lab</a> demonstrates scheduling and stale-event checks. The existing v3 CockroachDB/OPA harness is unchanged; distributed scheduling, leases and fences remain pilot engineering work.')+
section('The three-lane contract',iso_diagram+table(['Lane','Work','Capacity and ordering'],[
['Authority guard','Scoped revisions, deny overlays, grant activation, lease/watermark and receipts','Dedicated reserved workers/connections; small transactions; rate-limit submissions. No scans, backfill or physical purge.'],
['Operational delivery','New/changed eligible business records and required small parent manifests','Reserved throughput and per-entity fairness; preserve aggregate/resource order; independent destination queues.'],
['Policy reconciliation','Historical backfill, projection narrowing/purge, bulk repair and migration','Budgeted resumable batches, bytes/IOPS/concurrency caps, separate retry/quarantine. Separate deletion deadlines.']]))+
section('A queue is only one part of isolation','<p>Isolate the source relay, broker partitions, workers, connection pools and recipient import budget. A single outbox scanner draining bulk rows first simply moves the bottleneck upstream. Use separate outbox tables/changefeeds or independently claimable lanes. Raw snapshots remain in the home region; only authorised projections cross borders.</p><p>Reserve guard and operational capacity against measured limiting resources. Bound background transaction size and duration so an in-flight bulk statement cannot monopolise locks or I/O. Per-entity fairness prevents one legal entity consuming the entire lane. Shared-disk contention still needs admission control; extra queues cannot promise zero interference.</p>')+
section('Policy activation is bounded',table(['Transaction','Atomic contents','Follow-up outside the caller transaction'],[
['Business operation','Changed rows + resource/data versions + operational intent + audit intent + idempotency receipt','Current-policy export, recipient delta application and visibility receipt.'],
['Policy change','Desired facts + monotonic scoped authority revision + guard intent + one reconciliation cursor + audit intent','Guard propagation/readiness; asynchronously enumerate affected resources.'],
['Recipient guard','Monotonic fence and verified authority facts + cache/lease invalidation state + receipt','Live purge and broad projection repair run in bounded background batches.'],
['Recipient operational apply','Validate current fence/data version/placement + delta + inbox + manifest + audit intent','Acknowledge after commit. No total ordering between lanes assumed.'],
['Background purge','Validate current restriction and expected manifest revision + bounded delete + checkpoint','An old purge must not remove a projection from a subsequent grant.']]))+
section('Restrictions and grants have different readiness rules',table(['Change','Fast authority path','Operational behaviour','Background work'],[
['Remove UK contact access','Stop new source exports at source commit; deliver scoped recipient deny/fence','Affected UK reads/imports deny once fenced or authority expires. Other eligible work continues.','Remove existing contact copies and produce live-purge evidence.'],
['Grant a new UK dataset','Prepare compatible rules/facts; activate destination-bound grant','Fresh records can flow with parent closure before all historical data arrives.','Populate historical records with a resumable scan.'],
['Change generic Rego logic','Canary and prepare compatible bundles before activation; restrictive overlay or targeted denial if unready','No stale rule instance can silently use new rights. Only affected routes lose readiness.','Re-evaluate existing projections under the new rule revision.'],
['Move physical store','Fence old placement/home epochs and stage an approved new destination','Existing valid routes continue until controlled cutover; no dual authoritative writer.','Snapshot plus changes, reconciliation and a separately approved migration cutover.']]))+
call('An asynchronous policy change cannot mean stale permission','Source commit does not instantaneously revoke an already in-flight packet or a disconnected receiver. Remote enforcement is confirmed by a fence acknowledgement or the approved authority-lease expiry bound. Strict reads use current source authority; the proposed bounded-local alternative still requires bank approval. During an authority gap, fail closed only for affected scopes. Physical purge remains a separate milestone.')+
section('Worked sequence: UK contact restriction',flow([
('Commit at SG · t=5s','Revision 8 and a guard intent commit with a reconciliation cursor. No 20,000-row scan in the policy transaction. New UK contact exports stop.'),
('Guard at UK · t=5.20s assumed','UK durably applies the fence; affected reads and imports deny. The 200ms path is a modelling assumption, not a measured guarantee.'),
('Operational work proceeds','Unchanged eligible party/relationship deliveries use their reserved lane. A contact update may still commit at its permitted SG home.'),
('Stale event rechecked','A queued revision 7 event must reauthorise. Revision 8 denies UK contact fields, irrespective of the event’s newer business version.'),
('Reconcile existing copies','Background workers remove old UK contact projections, bounded by their budget. Access remains blocked while physical cleanup is pending.')]))+
section('Cross-lane race and dependency rules',table(['Race','Required behaviour'],[
['Old policy event after new restriction','Reload current facts; never trust the event’s older allow decision.'],
['New data before required guard state','Park only that scope/destination; wait for valid facts or fail closed. No retry loop blocking unrelated records.'],
['Historical backfill after operational update','Compare resource data versions inside recipient transaction; do not overwrite newer content.'],
['Old purge after regrant','Compare authority and manifest versions against current state; obsolete deletion becomes a no-op/replan.'],
['New child before historical parent','Fetch an authorised minimal parent manifest in bounded work, or park the dependent record. Do not wait for the whole backfill.'],
['Missing revocation message despite heartbeat','Lease renewal requires a contiguous applied revocation watermark; heartbeat alone is insufficient.'],
['Rapid policy revisions','Coalesce desired-state reconciliation cursors; preserve audit and mandatory denial obligations. Do not coalesce business events that require every transition.']]))+
section('Configuration skeleton',code('''# Illustrative service budgets, not CockroachDB or Kafka configuration.
regional_work_classes:
  guard: {reserved_units_per_second: 50, pool: guard, max_batch_units: 1}
  operational: {reserved_units_per_second: 700, pool: operational}
  reconciliation: {max_units_per_second: 250, pool: bulk, resumable: true}
  total_units_per_second: 1000
  policy_submit_admission: scoped_and_rate_limited
  background_pressure_response: throttle_then_pause
  authority_missing: fail_closed_for_affected_scope
  stale_intent: reauthorise_and_rebuild_from_current_state
# Also budget bytes, DB concurrency, transaction duration and measured IOPS.
# Unused reservations may be lent only through bounded work that can yield.
# No idle-capacity borrowing is implemented in the browser model.''','YAML'))+
section('Control API and UX contract',code('''POST /control/policy-changes
{ "scope": {"ownerEntity": "LE-SG-01", "table": "contact_info"},
  "expectedRevision": 7, "change": {"denyDestination": "LE-GB-02"},
  "idempotencyKey": "synthetic-request" }

202 Accepted
{ "operationId": "synthetic-policy-op", "policyRevision": 8,
  "sourceAuthority": "effective",
  "destinations": [{"entity": "LE-GB-02", "guardStatus": "pending"}],
  "reconciliation": {"status": "queued", "cursor": "opaque"},
  "livePurge": "pending" }
# Outline only; this endpoint is not added to the current harness.
# Show accepted, authority-enforced, data-ready and physically-converged separately.''','API outline'))+
section('Observe each lane separately','<p>The monitor shows operational arrival/completion and p95/p99, guard acknowledgement age and affected-scope freshness, plus bulk progress and purge deadlines. A large bulk backlog can coexist with healthy operations; it is not automatically an operational incident. An overdue restriction acknowledgement is a separate security/SLO signal. Regional OTel attributes include work.class, cell, operation and bounded outcome; exclude customer identifiers from metric labels. Audit remains complete and regionally governed even where traces are sampled.</p><p>Expose target, simulated and measured values separately. For grants, show fresh-record readiness separately from historical completeness. For restrictions, show access blocked separately from physical deletion, including offline targets and retained backups.</p>')+
section('Model and engineering acceptance','<p>The lab uses equal total capacity: 1,000 work units/s in both cases, with 50 reserved for guard. A shared FIFO gives the remaining 950 to operations and bulk; the isolated case reserves 700 operational and 250 bulk. At 500 operational arrivals/s, a 20,000-task burst adds queueing only to the shared FIFO in this idealised model. At 800 arrivals/s the isolated operational lane overloads. Each task costs one unit and transport adds 60ms. These are scheduling assumptions, not benchmark numbers.</p><p>Before pilot, sustain agreed peak while reconciling a 100M-relationship policy change. Require existing operational SLOs and an initial comparison target of no more than 10% operational p99 degradation versus the same hardware without bulk work. Measure errors and attempted requests. Test stopped guard transport, worker death, disk contention, rapid policy changes, stale events and regrant/purge races. Adjust budgets from evidence; do not claim the numerical illustration proves resource isolation.</p><div class="link-grid"><a href="'+iso_lab+'"><span>INTERACTIVE MODEL</span><h3>Run the queue comparison →</h3><p>Change the policy batch and foreground arrival rate; replay the timeline.</p></a><a href="https://sovereign-data-monitor.paulcull.chatgpt.site/isolation/work-isolation.md"><span>DESIGN DECISION</span><h3>Read the full ADR →</h3><p>Contracts, extension points, race rules and acceptance scenarios.</p></a></div>')+
section('Primary platform references',sources([('OPA bundles: eventual distribution and activation','https://www.openpolicyagent.org/docs/management-bundles'),('CockroachDB CDC: duplicates and ordering limits','https://docs.cockroachlabs.com/docs/stable/changefeed-messages')])),
iso_prompt+'''Implement a thin slice using PolicyAuthority, GuardRelay, OperationalRelay, ReconciliationScanner, AdmissionGate and CapacityGovernor interfaces. Keep three separate outbox claim paths and transport/worker pools. Stage generic bundles; commit scoped epochs and one cursor rather than enumerating records in a policy call. Implement current-state OPA export/import/read admission, durable monotonic fences, versioned manifests and retry/idempotency. Parameterise service, connection, byte and transaction budgets; use per-entity/destination fairness. Create a 100M-scope synthetic policy campaign and open-arrival operational load harness. Test delayed guard, obsolete backfill, old purge after regrant, missing parent and shared-disk contention. Provide a small local demonstration and an ADR; do not claim production isolation until measured. Keep the original v3 harness and this proposed design distinctly labelled.''')

for p in pages:
 if p['slug'] in ['index','architecture','opa','transactions','service-transactions','federation','lifecycle','observability','engineering','performance-scale','pilot-plan','apis','control-plane']:
  p['body']=call('Operational isolation decision · edition 07','Policy guard, operational delivery and bulk reconciliation have separate resource budgets. Policy activation performs bounded authority work; broad data movement runs independently. <a href="work-isolation.html">Read the revised contract</a> · <a href="'+iso_lab+'">Run the isolation model</a>. The v3 runtime remains a thin serial harness.')+p['body']
  p['prompt']=iso_prompt+p['prompt']
 if p['slug']=='transactions':
  p['body']=p['body'].replace('Policy version + grant generation + desired placement + reconciliation job + audit intent','Scoped policy version + grant generation + desired placement + guard intent + one reconciliation cursor + audit intent')
  p['body']=p['body'].replace('Increase fence generation + block reads/imports + delete live projection + purge job/audit intent','Increase fence generation + block reads/imports + purge intent/audit intent; physical deletion uses separate bounded transactions')
 if p['slug']=='index':p['kicker']='Operational federation / Design edition 07'
